const e=[{id:"sv-1-1241",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"What does the Japanese term **muda** mean in Lean?",options:["Waste: any activity that uses resources without adding customer value","Unevenness: irregular workload or flow through a process","Overburden: pushing people or equipment beyond their capacity","Continuous improvement: small, ongoing changes to a process"],answer:0,hint:"Recall the three Japanese “mu-” words and which one the seven elements belong to.",steps:[{title:"Key idea",body:"The book calls the seven elements “the 7 basic elements of waste (**muda** in Japanese)”."},{title:"Eliminate look-alikes",body:"Mura = unevenness, muri = overburden, kaizen = continuous improvement."}],final:"Muda = waste → answer **A**",whyWrong:["","Incorrect — unevenness is mura, a separate Japanese Lean term.","Incorrect — overburden is muri, not muda.","Incorrect — continuous improvement is kaizen, not muda."],trap:"Mura and muri sound alike but are not the seven wastes.",bookRef:"Book p. 502"},{id:"sv-1-1242",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which describes the waste of **Correction**?",options:["Doing more work on an item than the customer requires","Effort spent finding and fixing errors, including the rework and inspection they cause","Making more output, or making it earlier, than the next step needs","Work or people standing idle until an upstream input is ready"],answer:1,hint:"Correction is the syllabus name for the waste caused by mistakes.",steps:[{title:"Key idea",body:"Correction = defects plus all the rework, repeat work and inspection triggered by them."},{title:"Eliminate look-alikes",body:"The other options define Overprocessing, Overproduction and Waiting."}],final:"Correction = fixing errors → answer **B**",whyWrong:["Incorrect — extra work beyond the requirement is Overprocessing.","","Incorrect — too many or too soon is Overproduction.","Incorrect — idle time is Waiting."],bookRef:"Book p. 502"},{id:"sv-1-1243",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which describes **Inventory** as one of the seven elements of waste?",options:["Material, information or work-in-progress beyond what the process needs right now","Unnecessary movement of people within their workstation","Moving materials or information between locations more than necessary","Effort spent fixing errors after they have been made"],answer:0,hint:"Inventory is a quantity sitting in the system, not an activity.",steps:[{title:"Key idea",body:"Inventory = stock, backlogs or WIP beyond current need. It covers information (queued tickets) as well as goods."},{title:"Eliminate look-alikes",body:"The other options describe Motion, Conveyance and Correction."}],final:"Inventory = excess stock, information or WIP → answer **A**",whyWrong:["","Incorrect — people moving within the work area is Motion.","Incorrect — movement between locations is Conveyance.","Incorrect — fixing errors is Correction."],bookRef:"Book p. 502"},{id:"sv-1-1244",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which describes the waste of **Waiting**?",options:["Work-in-progress piling up between two process steps","People, equipment or work idle because something upstream is not ready","Repeating a task because the first attempt contained an error","Searching for tools that are not stored at the point of use"],answer:1,hint:"Waiting is idle time; ask who or what is standing still.",steps:[{title:"Key idea",body:"Waiting = idle time of people, equipment or work because an input, approval or resource is not ready."},{title:"Eliminate look-alikes",body:"A queue seen as a quantity is Inventory; searching is Motion; repeat work is Correction."}],final:"Waiting = idle time → answer **B**",whyWrong:["Incorrect — a pile of queued work seen as a quantity is Inventory.","","Incorrect — repeat work caused by errors is Correction.","Incorrect — searching and reaching are Motion."],bookRef:"Book p. 502"},{id:"sv-1-1245",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which describes the waste of **Overprocessing**?",options:["Doing more work, or work to a higher standard, than the customer requires","Producing more units, or producing them sooner, than demand requires","Holding more stock or work-in-progress than the process needs","Passing work between too many teams or locations"],answer:0,hint:"Overprocessing is judged against what the customer actually needs on each item.",steps:[{title:"Key idea",body:"Overprocessing = extra effort or specification per item: extra approvals, duplicate entry, polishing beyond spec."},{title:"Eliminate look-alikes",body:"Quantity/timing is Overproduction; stock is Inventory; hand-offs are Conveyance."}],final:"Overprocessing = more work per item than required → answer **A**",whyWrong:["","Incorrect — too many or too soon is Overproduction.","Incorrect — excess stock or WIP is Inventory.","Incorrect — extra hand-offs between locations are Conveyance."],bookRef:"Book p. 502"},{id:"sv-1-1246",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which describes the waste of **Overproduction**?",options:["Applying a tighter tolerance than the drawing specifies","Making more, or making it earlier, than the next step or customer needs","Fixing defective items so they can be used","Operators bending and reaching to pick up parts"],answer:1,hint:"Overproduction is about quantity and timing.",steps:[{title:"Key idea",body:"Overproduction = too many, or too soon, compared with real demand."},{title:"Eliminate look-alikes",body:"Tight tolerance = Overprocessing; fixing = Correction; reaching = Motion."}],final:"Overproduction = too many or too soon → answer **B**",whyWrong:["Incorrect — a tighter-than-needed specification is Overprocessing.","","Incorrect — fixing defects is Correction.","Incorrect — bending and reaching are Motion."],bookRef:"Book p. 502"},{id:"sv-1-1247",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"In the eight-waste (DOWNTIME) list, which name is used for the syllabus element **Correction**?",options:["Defects","Extra-processing","Non-utilized talent","Transportation"],answer:0,hint:"Three of the seven are renamed in DOWNTIME; one waste is added.",steps:[{title:"Key idea",body:"Renames: Correction → Defects, Conveyance → Transportation, Overprocessing → Extra-processing."},{title:"Apply to the stem",body:"The stem asks for Correction, so the DOWNTIME name is Defects."}],final:"Correction ↔ Defects → answer **A**",whyWrong:["","Incorrect — Extra-processing is the eight-waste name for Overprocessing.","Incorrect — Non-utilized talent is the added eighth waste with no match among the seven.","Incorrect — Transportation is the eight-waste name for Conveyance."],bookRef:"Syllabus p. 2"},{id:"sv-1-1248",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"The eight-waste list includes **Extra-processing**. Which syllabus 1.4.4 element does it correspond to?",options:["Overproduction","Correction","Conveyance","Overprocessing"],answer:3,hint:"Match the renamed wastes: Defects, Transportation, Extra-processing.",steps:[{title:"Key idea",body:"Extra-processing = doing more work than needed, which the syllabus calls Overprocessing (book: “Processing”)."},{title:"Eliminate look-alikes",body:"Overproduction is unchanged; Correction ↔ Defects; Conveyance ↔ Transportation."}],final:"Extra-processing ↔ Overprocessing → answer **D**",whyWrong:["Incorrect — Overproduction keeps the same name in both lists.","Incorrect — Correction corresponds to Defects in the eight-waste list.","Incorrect — Conveyance corresponds to Transportation in the eight-waste list.",""],trap:"“Over-” prefixes: Overprocessing (per item) is not Overproduction (quantity).",bookRef:"Syllabus p. 2"},{id:"sv-1-1249",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"According to the book, why is **identifying** the seven wastes important in an improvement project?",options:["Identifying waste removes the need to measure the process","Identifying waste proves the process is statistically capable","Identifying waste replaces the need for a project charter","Identifying waste is the first step toward eliminating it"],answer:3,hint:"The book links seeing waste to removing it.",steps:[{title:"Key idea",body:"Book p. 502: identifying waste is the first step toward eliminating it."},{title:"Eliminate look-alikes",body:"Naming waste does not replace measurement, capability analysis or the charter."}],final:"Identify first, then eliminate → answer **D**",whyWrong:["Incorrect — waste must still be measured; naming it does not replace data collection.","Incorrect — capability is shown by capability analysis, not by naming waste.","Incorrect — the charter is still needed; the book says it already points to waste.",""],bookRef:"Book p. 502"},{id:"sv-1-1250",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"What does the book say about the link between waste and Six Sigma projects?",options:["Waste is often the root of a Six Sigma project","Waste only matters after the Control phase is complete","Waste is a Lean idea that Six Sigma projects should ignore","Waste can only be found in manufacturing projects"],answer:0,hint:"Recall the book’s comment that your charter and primary metric already point at waste.",steps:[{title:"Key idea",body:"Book p. 502: waste is often the root of a Six Sigma project, even if the word “waste” was never used."},{title:"Eliminate look-alikes",body:"Waste is not limited to manufacturing and is not separate from Six Sigma."}],final:"Waste is often the project’s root → answer **A**",whyWrong:["","Incorrect — waste is identified from the start, not only after Control.","Incorrect — the book treats waste as central to Six Sigma projects.","Incorrect — waste appears in every process, including services."],bookRef:"Book p. 502"},{id:"sv-1-1251",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"How is the idea of “producing to actual demand” applied to reduce **Overproduction**?",options:["By running large batches so that machines stay fully utilised","By starting work only when a downstream step or customer signals a need","By building stock to the monthly forecast in case demand rises","By adding an inspection step after each process step"],answer:1,hint:"Think pull, not push.",steps:[{title:"Key idea",body:"Overproduction is cut by producing to real demand: pull signals, smaller batches, just-in-time release."},{title:"Eliminate look-alikes",body:"Large batches and forecast-driven building cause Overproduction; inspection relates to Correction."}],final:"Pull to demand → answer **B**",whyWrong:["Incorrect — large batches driven by utilisation create Overproduction.","","Incorrect — producing to forecast instead of real demand is how Overproduction arises.","Incorrect — extra inspection targets Correction, not Overproduction."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1252",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"How is the waste of **Motion** typically reduced?",options:["By routing parts directly between sites with fewer hand-offs","By setting work-in-progress limits between process steps","By improving layout and storing tools and materials at the point of use","By removing approval steps the customer does not need"],answer:2,hint:"Motion is people moving within the workplace; the fix brings things closer.",steps:[{title:"Key idea",body:"Motion countermeasures: ergonomic layout, point-of-use storage, single dashboards. 5S is the classic tool."},{title:"Eliminate look-alikes",body:"Direct routing = Conveyance; WIP limits = Inventory; fewer approvals = Overprocessing."}],final:"Point-of-use storage and layout → answer **C**",whyWrong:["Incorrect — direct routing reduces Conveyance, the movement of items between locations.","Incorrect — WIP limits reduce Inventory.","","Incorrect — removing unneeded approvals reduces Overprocessing."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1253",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"How is the waste of **Conveyance** typically reduced?",options:["By storing frequently used tools within arm’s reach of the operator","By confirming customer requirements before adding process steps","By balancing workload so no step sits idle","By co-locating steps and routing work directly with fewer hand-offs"],answer:3,hint:"Conveyance is items or information travelling between locations.",steps:[{title:"Key idea",body:"Conveyance countermeasures: co-locate, route directly, reduce hand-offs and double handling."},{title:"Eliminate look-alikes",body:"Arm’s-reach storage = Motion; VOC checks = Overprocessing; load balancing = Waiting."}],final:"Co-locate and route directly → answer **D**",whyWrong:["Incorrect — point-of-use storage reduces Motion within the workstation.","Incorrect — checking the VOC reduces Overprocessing.","Incorrect — balancing workload reduces Waiting.",""],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1254",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"How is the waste of **Correction** reduced at its source?",options:["By mistake-proofing the process and removing the root causes of errors","By adding a 100% final inspection before work leaves the team","By holding more safety stock to replace defective items","By adding a manager sign-off to every transaction"],answer:0,hint:"Prevention beats detection.",steps:[{title:"Key idea",body:"Correction falls when errors are prevented: error-proofing, clear operational definitions, root-cause fixes."},{title:"Apply to the stem",body:"Inspection, extra stock and sign-offs only catch or cover errors; they do not stop them."}],final:"Prevent errors at the root → answer **A**",whyWrong:["","Incorrect — inspection finds errors after the fact and is itself non-value-added.","Incorrect — extra stock adds Inventory and hides defects rather than preventing them.","Incorrect — extra sign-offs add Overprocessing without stopping errors."],trap:"More checkers feel safe but add waste.",bookRef:"Syllabus 1.4.4"},{id:"sv-1-1255",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which waste is measured in **time** and directly stretches the lead time of every affected item?",options:["Inventory","Motion","Overprocessing","Waiting"],answer:3,hint:"Which waste is literally idle time?",steps:[{title:"Key idea",body:"Waiting is idle time when work cannot proceed; it adds directly to lead time."},{title:"Eliminate look-alikes",body:"Inventory is a quantity; Motion is movement; Overprocessing is extra effort."}],final:"Waiting = idle time → answer **D**",whyWrong:["Incorrect — Inventory is measured as a quantity of stock or WIP, not as idle time.","Incorrect — Motion is unnecessary movement; it can cost time but is defined by movement.","Incorrect — Overprocessing is extra work per item, defined by effort, not idle time.",""],bookRef:"Book p. 502"},{id:"sv-1-1256",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"A stack of 300 rejected invoices sits in a tray while a clerk re-keys each one. Which pairing correctly names the two wastes?",options:["The stack is Correction; the re-keying is Inventory","The stack is Inventory; the re-keying is Correction","The stack is Waiting; the re-keying is Overprocessing","The stack is Overproduction; the re-keying is Motion"],answer:1,hint:"Correction is effort spent fixing; Inventory is a quantity sitting in the system.",steps:[{title:"Key idea",body:"Book p. 502 pair: a stack of rejected work is Inventory; the work of fixing it is Correction."},{title:"Apply to the stem",body:"Tray of 300 invoices = quantity → Inventory. Re-keying = fixing errors → Correction."}],final:"Stack = Inventory, re-keying = Correction → answer **B**",whyWrong:["Incorrect — this reverses them: a quantity sitting is Inventory, effort fixing errors is Correction.","","Incorrect — re-keying fixes an error, so it is Correction, not extra work on a good item.","Incorrect — nothing was produced ahead of demand, and re-keying is not movement."],bookRef:"Book p. 502"},{id:"sv-1-1257",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"The same queue of 500 orders can be described as two different wastes. When is it best described as **Waiting**?",options:["When the question counts the number of orders held in the system","When the orders are moved between two offices","When the question looks at the idle time of the customer or the person","When the orders must be re-entered because of errors"],answer:2,hint:"Two views of one queue: the item’s view and the person’s view.",steps:[{title:"Key idea",body:"From the work item’s view a queue is Inventory (WIP). From the person’s or customer’s view, the idle time is Waiting."},{title:"Apply to the stem",body:"The stem asks when it is Waiting → the idle-time view."}],final:"Idle-time view = Waiting → answer **C**",whyWrong:["Incorrect — counting items held in the system is the Inventory view.","Incorrect — moving orders between locations is Conveyance.","","Incorrect — re-entering because of errors is Correction."],bookRef:"Book p. 502"},{id:"sv-1-1258",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which pair of definitions correctly separates **Overproduction** from **Overprocessing**?",options:["Overproduction: too much work per item. Overprocessing: too many or too soon","Overproduction: fixing errors. Overprocessing: holding excess stock","Overproduction: idle people. Overprocessing: moving items between sites","Overproduction: too many or too soon. Overprocessing: too much work per item"],answer:3,hint:"Quantity and timing versus effort and specification.",steps:[{title:"Key idea",body:"Overproduction is about quantity and timing; Overprocessing is about effort or specification on each item."},{title:"Eliminate look-alikes",body:"The swapped pair is the classic trap; the others mix in Correction, Inventory, Waiting and Conveyance."}],final:"Quantity/timing vs effort per item → answer **D**",whyWrong:["Incorrect — the definitions are swapped.","Incorrect — fixing errors is Correction and excess stock is Inventory.","Incorrect — idle people is Waiting and moving items is Conveyance.",""],trap:"1,000 brochures for 400 needed = Overproduction; laminating them = Overprocessing.",bookRef:"Book p. 502"},{id:"sv-1-1259",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Much rework is never shown on the official process map and lives in the **hidden factory**. Which of the seven wastes does the hidden factory mostly contain?",options:["Conveyance","Correction","Overproduction","Waiting"],answer:1,hint:"The hidden factory is the unofficial rework loop.",steps:[{title:"Key idea",body:"The hidden factory is the unrecorded work spent fixing errors; it shows up as cost of poor quality."},{title:"Apply to the stem",body:"Fixing errors is the waste of Correction."}],final:"Hidden factory = Correction → answer **B**",whyWrong:["Incorrect — Conveyance is movement between locations; the hidden factory is about unseen rework.","","Incorrect — Overproduction is making too much or too soon, not fixing errors.","Incorrect — Waiting is idle time, not the rework loops of the hidden factory."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1260",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"The book notes that removing waste can also reduce **outliers** in a project metric. What is the reason?",options:["Different people, machines and procedures carry different amounts of waste","Removing waste narrows the specification limits set by the customer","Removing waste deletes extreme values from the data set","Removing waste makes every process normally distributed"],answer:0,hint:"Uneven waste across people and machines creates uneven results.",steps:[{title:"Key idea",body:"Book p. 502: because different people, machines and procedures carry different amounts of waste, removing it makes results more consistent."},{title:"Eliminate look-alikes",body:"Waste removal does not change customer specs, delete data or force normality."}],final:"Uneven waste → outliers → answer **A**",whyWrong:["","Incorrect — specification limits come from the customer, not from waste removal.","Incorrect — outliers fall because the process changes, not because data are deleted.","Incorrect — waste removal does not guarantee normality."],bookRef:"Book p. 502"},{id:"sv-1-1261",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"A contact centre agent types the same customer details into the CRM and then again into the billing system. Which waste is this?",options:["Correction","Inventory","Motion","Overprocessing"],answer:3,hint:"Duplicate effort on a correct item is judged against what the customer needs.",steps:[{title:"Key idea",body:"Duplicate data entry is a classic Overprocessing sign: extra work that adds nothing for the customer."},{title:"Eliminate look-alikes",body:"Correction needs an error; Inventory needs a quantity; Motion needs movement."}],final:"Duplicate entry = Overprocessing → answer **D**",whyWrong:["Incorrect — no error is being fixed; the first entry was correct.","Incorrect — no stock or queue is building up.","Incorrect — the issue is the repeated work, not movement of the agent.",""],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1262",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"An operator stands beside a machine and watches it complete its automatic cycle before loading the next part. Which waste is the operator’s time?",options:["Motion","Waiting","Overprocessing","Conveyance"],answer:1,hint:"Who is idle, and why?",steps:[{title:"Key idea",body:"Watching a machine run is idle time: the person cannot proceed until the machine finishes."},{title:"Eliminate look-alikes",body:"There is no movement (Motion, Conveyance) and no extra work (Overprocessing)."}],final:"Machine-watching = Waiting → answer **B**",whyWrong:["Incorrect — the operator is standing still, not moving unnecessarily.","","Incorrect — no extra work is being done on the part.","Incorrect — no material is moving between locations."],bookRef:"Book p. 502"},{id:"sv-1-1263",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"A supplier delivers a whole month of parts in one shipment, although the line uses them a few boxes per day. Which waste does this create?",options:["Correction","Inventory","Overprocessing","Waiting"],answer:1,hint:"Think of material held beyond current need.",steps:[{title:"Key idea",body:"Stock beyond what the process needs right now is Inventory."},{title:"Eliminate look-alikes",body:"There is no extra effort, no error and no idle time."}],final:"Month of parts = Inventory → answer **B**",whyWrong:["Incorrect — nothing is defective or being fixed.","","Incorrect — no extra work is done on each part.","Incorrect — the line is not idle; it has more parts than it needs."],bookRef:"Book p. 502"},{id:"sv-1-1264",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"What is the key difference between **Correction** and **Overprocessing**?",options:["Correction adds unneeded work; Overprocessing fixes an error","Correction is movement of items; Overprocessing is movement of people","Correction fixes an error; Overprocessing adds unneeded work to an item done right","Correction is idle time; Overprocessing is excess stock"],answer:2,hint:"Ask: was there a mistake?",steps:[{title:"Key idea",body:"Correction exists only because something went wrong. Overprocessing is extra effort on a correct item."},{title:"Eliminate look-alikes",body:"Swapped definitions and movement/idle/stock wastes are look-alikes from other pairs."}],final:"Error fixed vs extra work on a good item → answer **C**",whyWrong:["Incorrect — the definitions are swapped.","Incorrect — those describe Conveyance and Motion.","","Incorrect — those describe Waiting and Inventory."],bookRef:"Book p. 502"},{id:"sv-1-1265",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which is a typical cause of excess **Inventory** in a process?",options:["Tools stored far from the operator","Unclear customer requirements leading to extra approvals","Missing operational definitions leading to errors","Large batch sizes and unbalanced capacity between steps"],answer:3,hint:"What makes work pile up between steps?",steps:[{title:"Key idea",body:"Inventory builds when upstream steps release large batches or run faster than downstream steps can absorb."},{title:"Eliminate look-alikes",body:"Distant tools = Motion; unclear requirements = Overprocessing; missing definitions = Correction."}],final:"Large batches, unbalanced capacity → Inventory → answer **D**",whyWrong:["Incorrect — tools stored far away cause Motion.","Incorrect — unclear requirements leading to extra steps cause Overprocessing.","Incorrect — missing definitions lead to errors and therefore Correction.",""],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1266",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which statement about the seven elements of waste in syllabus topic 1.4.4 is CORRECT?",options:["They include Correction, Conveyance and Overprocessing","They include Non-utilized talent as the seventh element","They use the names Defects, Transportation and Extra-processing","They list Variation as a separate element of waste"],answer:0,hint:"Recall the exact syllabus words: O-C-I-M-O-C-W.",steps:[{title:"Key idea",body:"Syllabus 1.4.4: Overproduction, Correction, Inventory, Motion, Overprocessing, Conveyance, Waiting."},{title:"Eliminate look-alikes",body:"Defects/Transportation/Extra-processing are DOWNTIME names; Non-utilized talent and variation are not among the seven."}],final:"Correction, Conveyance and Overprocessing are syllabus terms → answer **A**",whyWrong:["","Incorrect — Non-utilized talent appears only in the eight-waste list.","Incorrect — those are the eight-waste (DOWNTIME) names.","Incorrect — variation is the focus of Six Sigma, not one of the seven wastes."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1267",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which statement about the waste of **Motion** is CORRECT?",options:["It refers to moving materials between warehouses and sites","It includes excessive clicking and screen-switching by a person at a workstation","It is called Transportation in the eight-waste list","It occurs only in manufacturing, never in office work"],answer:1,hint:"Motion is about people (or equipment) moving within the work area — physically or digitally.",steps:[{title:"Key idea",body:"Motion = unnecessary movement of people within the workplace: reaching, searching, walking, clicking through screens."},{title:"Eliminate look-alikes",body:"Between-site movement is Conveyance (Transportation); Motion exists in service work too."}],final:"Screen-hopping counts as Motion → answer **B**",whyWrong:["Incorrect — moving materials between locations is Conveyance.","","Incorrect — Motion keeps its name; Transportation corresponds to Conveyance.","Incorrect — Motion appears in offices too, for example searching across screens."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1268",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"Which statement about **Overproduction** is CORRECT?",options:["It means applying a higher standard to each item than the customer needs","It is the eight-waste name for the syllabus element Inventory","It can hide defects until much later, when the stored output is finally used","It only occurs when the total quantity made exceeds annual demand"],answer:2,hint:"Think about what happens to output that is made before anyone needs it.",steps:[{title:"Key idea",body:"Extra or early output is stored, moved and counted, and defects inside it surface only later — one reason it is called the worst waste."},{title:"Eliminate look-alikes",body:"Higher standard = Overprocessing; Inventory is its own element; timing counts as well as quantity."}],final:"Overproduction hides defects → answer **C**",whyWrong:["Incorrect — a higher standard per item is Overprocessing.","Incorrect — Inventory keeps its name; Overproduction is a separate waste.","","Incorrect — making items too early is Overproduction even if the quantity is right."],bookRef:"Book p. 502"},{id:"sv-1-1269",phase:1,topic:"1.4.4",qtype:"concept",difficulty:3,stem:"Which statement about the waste of **Correction** is CORRECT?",options:["It is removed most effectively by adding more final inspectors","It describes extra work done on items that were already right","It is called Extra-processing in the eight-waste list","It includes the inspection and repeat work that errors trigger, not only the defect itself"],answer:3,hint:"Correction covers the whole cost of a mistake.",steps:[{title:"Key idea",body:"Correction = defects plus the rework, inspection and repeat effort they cause."},{title:"Eliminate look-alikes",body:"More inspectors do not prevent errors; extra work on good items is Overprocessing; DOWNTIME calls it Defects."}],final:"Correction includes triggered inspection and rework → answer **D**",whyWrong:["Incorrect — inspection detects errors after the fact and is itself non-value-added.","Incorrect — extra work on correct items is Overprocessing.","Incorrect — Correction corresponds to Defects; Extra-processing is Overprocessing.",""],bookRef:"Book p. 502"},{id:"sv-1-1270",phase:1,topic:"1.4.4",qtype:"concept",difficulty:1,stem:"Which statement about waste in **service** processes is CORRECT?",options:["All seven elements of waste can be found in service and office work","Only Waiting and Inventory can occur in service processes","Waste in services cannot be identified without a factory floor","Services have a separate list of seven wastes from manufacturing"],answer:0,hint:"Waste is about value to the customer, not about machines.",steps:[{title:"Key idea",body:"Queued tickets (Inventory), re-keyed invoices (Correction), approval delays (Waiting), ticket hand-offs (Conveyance) — all seven occur in services."},{title:"Eliminate look-alikes",body:"There is one list, and it is not limited to Waiting and Inventory."}],final:"All seven apply to services → answer **A**",whyWrong:["","Incorrect — every waste appears in services, such as duplicate entry (Overprocessing) and re-keying (Correction).","Incorrect — waste is identified in any process, physical or digital.","Incorrect — the same seven elements apply to both."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1271",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which statement about the waste of **Conveyance** is CORRECT?",options:["It applies only to physical goods carried by truck or forklift","It includes information moving between teams or locations, such as repeated hand-offs","It describes a person walking back and forth at a workstation","It keeps the same name, Conveyance, in the eight-waste list"],answer:1,hint:"Conveyance = items or information travelling between places.",steps:[{title:"Key idea",body:"Conveyance covers materials, products and information moved between locations more than necessary, including hand-offs."},{title:"Eliminate look-alikes",body:"A person moving locally is Motion; DOWNTIME calls Conveyance “Transportation”."}],final:"Information hand-offs are Conveyance → answer **B**",whyWrong:["Incorrect — information and documents moving between locations is also Conveyance.","","Incorrect — a person moving within the work area is Motion.","Incorrect — the eight-waste list calls it Transportation."],bookRef:"Book p. 502"},{id:"sv-1-1272",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which statement about the waste of **Overprocessing** is CORRECT?",options:["It means producing more units than the customer ordered","It always involves an error that must be fixed","It is judged against what the customer requires, so the Voice of the Customer defines it","It is the waste of moving products between sites"],answer:2,hint:"Overprocessing means “more than the customer needs” — so who defines the need?",steps:[{title:"Key idea",body:"Overprocessing is extra effort or a higher standard than the customer requires; confirming the VOC is the countermeasure."},{title:"Eliminate look-alikes",body:"More units = Overproduction; errors = Correction; movement = Conveyance."}],final:"VOC defines Overprocessing → answer **C**",whyWrong:["Incorrect — producing more units than ordered is Overproduction.","Incorrect — work that fixes an error is Correction.","","Incorrect — moving products between sites is Conveyance."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1273",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"Which statement about the waste of **Inventory** is CORRECT?",options:["It is the waste of people being idle while they wait for input","It is created mainly by tools stored far from the operator","It is removed by adding approval steps to purchasing","It includes work-in-progress between process steps, not only finished goods"],answer:3,hint:"Inventory = stock, information or WIP beyond current need.",steps:[{title:"Key idea",body:"Inventory covers raw material, WIP between steps, finished goods and queued information such as tickets."},{title:"Eliminate look-alikes",body:"Idle time = Waiting; distant tools = Motion; approvals = Overprocessing."}],final:"Inventory includes WIP → answer **D**",whyWrong:["Incorrect — idle people is Waiting; Inventory is the quantity held.","Incorrect — distant tools cause Motion.","Incorrect — extra approvals add Overprocessing and do not limit WIP.",""],bookRef:"Book p. 502"},{id:"sv-1-1274",phase:1,topic:"1.4.4",qtype:"statements",difficulty:2,stem:`Which statements about the seven elements and the eight-waste (DOWNTIME) list are CORRECT?

1. Conveyance is called Transportation in the eight-waste list.
2. Correction is called Defects in the eight-waste list.
3. Motion is called Movement in the eight-waste list.
4. Non-utilized talent is one of the seven elements in topic 1.4.4.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Three renames (Defects, Transportation, Extra-processing) and one addition.",steps:[{title:"Judge each statement",body:"**1** ✓ Transportation is the DOWNTIME name for Conveyance. **2** ✓ Defects is the DOWNTIME name for Correction. **3** ✗ Motion keeps its name in both lists. **4** ✗ Non-utilized talent is the added eighth waste."},{title:"Match to a house pair",body:"Only statements 1 and 2 are correct, which is the option “1 and 2”."}],final:"Statements 1 and 2 are the correct renames → answer **A**",whyWrong:["","Incorrect — statement 3 is false: Motion keeps its name in both lists.","Incorrect — statement 3 is false: Motion keeps its name in both lists; statement 4 is false: Non-utilized talent is the added eighth waste.","Incorrect — statement 4 is false: Non-utilized talent is the added eighth waste."],bookRef:"Syllabus p. 2"},{id:"sv-1-1275",phase:1,topic:"1.4.4",qtype:"statements",difficulty:3,stem:`Which two statements about **Motion** and **Conveyance** are CORRECT?

1. A pallet of modems trucked from a warehouse to a depot is Motion.
2. An engineer switching between four consoles to check one alarm is Motion.
3. A fault ticket passed between three resolver groups is Conveyance.
4. A nurse walking to a distant cabinet for supplies is Conveyance.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Ask what moves (person or item) and where (within the workstation or between locations).",steps:[{title:"Judge each statement",body:"**1** ✗ goods travelling between locations are Conveyance. **2** ✓ a person moving within the workstation is Motion. **3** ✓ information moving between teams is Conveyance. **4** ✗ a person walking within the workplace is Motion."},{title:"Match to a house pair",body:"Only statements 2 and 3 are correct, which is the option “2 and 3”."}],final:"Statements 2 and 3 classify correctly → answer **B**",whyWrong:["Incorrect — statement 1 is false: goods travelling between locations are Conveyance.","","Incorrect — statement 4 is false: a person walking within the workplace is Motion.","Incorrect — statement 1 is false: goods travelling between locations are Conveyance; statement 4 is false: a person walking within the workplace is Motion."],trap:"A walking person is Motion even when the walk is long.",bookRef:"Book p. 502"},{id:"sv-1-1276",phase:1,topic:"1.4.4",qtype:"statements",difficulty:2,stem:`Which statements about **Overproduction** are CORRECT?

1. It means doing too much work on each individual item.
2. It is another name for the waste of Inventory.
3. It includes producing earlier than the next step needs.
4. It often creates other wastes such as Inventory and Conveyance.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Overproduction = too many or too soon; it generates other wastes.",steps:[{title:"Judge each statement",body:"**1** ✗ too much work per item is Overprocessing. **2** ✗ Inventory is a separate element. **3** ✓ Overproduction covers timing (too soon) as well as quantity. **4** ✓ extra output must be stored and moved."},{title:"Match to a house pair",body:"Only statements 3 and 4 are correct, which is the option “3 and 4”."}],final:"Statements 3 and 4 describe Overproduction → answer **C**",whyWrong:["Incorrect — statement 1 is false: too much work per item is Overprocessing; statement 2 is false: Inventory is a separate element.","Incorrect — statement 2 is false: Inventory is a separate element.","","Incorrect — statement 1 is false: too much work per item is Overprocessing."],bookRef:"Book p. 502"},{id:"sv-1-1277",phase:1,topic:"1.4.4",qtype:"statements",difficulty:2,stem:`Which statements describe the waste of **Waiting**?

1. A software release, ready on Monday, sits until Thursday’s change-advisory board.
2. Three hundred orders are held in the system awaiting scheduling.
3. Signed contracts are couriered between three offices.
4. Patients sit idle in a ward until their test results come back.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Waiting is idle time caused by something upstream not being ready.",steps:[{title:"Judge each statement",body:"**1** ✓ work is idle because an approval is not ready. **2** ✗ a quantity of orders held is Inventory. **3** ✗ documents moving between offices is Conveyance. **4** ✓ people idle because an upstream input is not ready."},{title:"Match to a house pair",body:"Only statements 1 and 4 are correct, which is the option “1 and 4”."}],final:"Statements 1 and 4 are Waiting → answer **D**",whyWrong:["Incorrect — statement 2 is false: a quantity of orders held is Inventory.","Incorrect — statement 2 is false: a quantity of orders held is Inventory; statement 3 is false: documents moving between offices is Conveyance.","Incorrect — statement 3 is false: documents moving between offices is Conveyance.",""],bookRef:"Book p. 502"},{id:"sv-1-1278",phase:1,topic:"1.4.4",qtype:"statements",difficulty:3,stem:`Which statements about countermeasures for waste are CORRECT?

1. Work-in-progress limits address Inventory.
2. Pre-approving standard changes addresses Waiting.
3. Adding final inspectors removes Correction at its source.
4. Larger batch sizes reduce Overproduction.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Match each countermeasure to the waste it actually reduces.",steps:[{title:"Judge each statement",body:"**1** ✓ WIP limits stop work piling up. **2** ✓ pre-approval removes idle time for an approval. **3** ✗ inspection detects errors; prevention removes Correction. **4** ✗ larger batches create Overproduction."},{title:"Match to a house pair",body:"Only statements 1 and 2 are correct, which is the option “1 and 2”."}],final:"Statements 1 and 2 pair the right fixes → answer **A**",whyWrong:["","Incorrect — statement 3 is false: inspection detects errors; prevention removes Correction.","Incorrect — statement 3 is false: inspection detects errors; prevention removes Correction; statement 4 is false: larger batches create Overproduction.","Incorrect — statement 4 is false: larger batches create Overproduction."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1279",phase:1,topic:"1.4.4",qtype:"statements",difficulty:2,stem:`Which statements about the book’s treatment of waste are CORRECT?

1. Waste should be eliminated before it is identified.
2. Identifying waste is the first step toward eliminating it.
3. Waste is often the root of a Six Sigma project.
4. Once removed, wastes cannot return to the process.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Recall the book’s three points about waste on p. 502–503.",steps:[{title:"Judge each statement",body:"**1** ✗ identification comes first. **2** ✓ book p. 502. **3** ✓ book p. 502. **4** ✗ the book warns wastes can return if Lean tools are not used."},{title:"Match to a house pair",body:"Only statements 2 and 3 are correct, which is the option “2 and 3”."}],final:"Statements 2 and 3 match the book → answer **B**",whyWrong:["Incorrect — statement 1 is false: identification comes first.","","Incorrect — statement 4 is false: the book warns wastes can return if Lean tools are not used.","Incorrect — statement 1 is false: identification comes first; statement 4 is false: the book warns wastes can return if Lean tools are not used."],bookRef:"Book pp. 502–503"},{id:"sv-1-1280",phase:1,topic:"1.4.4",qtype:"statements",difficulty:2,stem:`Which statements are examples of **Overprocessing**?

1. A line builds 500 units when 300 were ordered.
2. An invoice keyed with the wrong cost centre is keyed again.
3. A manager signs every standard order the system has already validated.
4. A surface is polished to a finish the drawing does not require.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Overprocessing = extra work or a higher standard on an item that was already right.",steps:[{title:"Judge each statement",body:"**1** ✗ making more than ordered is Overproduction. **2** ✗ re-keying to fix an error is Correction. **3** ✓ extra approval beyond what the risk or customer requires. **4** ✓ a higher standard than the customer needs."},{title:"Match to a house pair",body:"Only statements 3 and 4 are correct, which is the option “3 and 4”."}],final:"Statements 3 and 4 are Overprocessing → answer **C**",whyWrong:["Incorrect — statement 1 is false: making more than ordered is Overproduction; statement 2 is false: re-keying to fix an error is Correction.","Incorrect — statement 2 is false: re-keying to fix an error is Correction.","","Incorrect — statement 1 is false: making more than ordered is Overproduction."],bookRef:"Book p. 502"},{id:"sv-1-1281",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

[?] is the Japanese word used for waste in Lean.`,options:["Kaizen","Muda","Mura","Muri"],answer:1,hint:"Three Japanese “mu-” words: waste, unevenness, overburden.",steps:[{title:"Key idea",body:"The book: “the 7 basic elements of waste (muda in Japanese)”."},{title:"Eliminate look-alikes",body:"Kaizen = improvement; mura = unevenness; muri = overburden."}],final:"Muda → answer **B**",whyWrong:["Incorrect — kaizen means continuous improvement.","","Incorrect — mura means unevenness in flow or workload.","Incorrect — muri means overburden."],bookRef:"Book p. 502"},{id:"sv-1-1282",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

The training book labels the syllabus element Overprocessing simply as [?].`,options:["Correction","Handling","Processing","Rework"],answer:2,hint:"The book’s list on p. 502 shortens one syllabus name.",steps:[{title:"Key idea",body:"Book p. 502 lists Correction, Overproduction, **Processing**, Conveyance, Inventory, Motion and Waiting."},{title:"Apply to the stem",body:"The syllabus name for “Processing” is Overprocessing."}],final:"Processing → answer **C**",whyWrong:["Incorrect — Correction is its own element in both the book and the syllabus.","Incorrect — handling is not a waste label in the book’s list.","","Incorrect — rework is part of Correction, not Overprocessing."],bookRef:"Book p. 502"},{id:"sv-1-1283",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

[?] is the unnecessary movement of materials, products or information between locations.`,options:["Conveyance","Inventory","Motion","Waiting"],answer:0,hint:"Things travelling between places versus people moving at the work area.",steps:[{title:"Key idea",body:"Conveyance = items or information moving between locations."},{title:"Eliminate look-alikes",body:"Motion is the people version, within the workstation."}],final:"Conveyance → answer **A**",whyWrong:["","Incorrect — Inventory is a quantity held, not movement.","Incorrect — Motion is people moving within the workstation.","Incorrect — Waiting is idle time."],bookRef:"Book p. 502"},{id:"sv-1-1284",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Overproduction is about quantity and [?], whereas Overprocessing is about the effort spent on each item.`,options:["cost","location","specification","timing"],answer:3,hint:"Overproduction = too many or too ___.",steps:[{title:"Key idea",body:"Overproduction is making too many, or too soon. Overprocessing is too much work or specification per item."},{title:"Apply to the stem",body:"Too soon = timing."}],final:"timing → answer **D**",whyWrong:["Incorrect — cost is a consequence of every waste, not what defines Overproduction.","Incorrect — location relates to Conveyance and Motion.","Incorrect — specification belongs to Overprocessing, the other half of the pair.",""],bookRef:"Book p. 502"},{id:"sv-1-1285",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:2,stem:`Identify the missing words in the following sentence.

A step that changes the form, fit or function of the product and that the customer is willing to pay for is [?].`,options:["business value-added","non-value-added","rework","value-added"],answer:3,hint:"The book’s value tests: form, fit or function, and the customer is willing to pay.",steps:[{title:"Key idea",body:"Book p. 117: value-added work changes form, fit or function and the customer would pay for it. Everything else is a candidate for waste."},{title:"Eliminate look-alikes",body:"Business value-added is required but not paid for; rework is Correction."}],final:"value-added → answer **D**",whyWrong:["Incorrect — business value-added steps are required by the business but not paid for by the customer.","Incorrect — non-value-added steps consume resources without such a change.","Incorrect — rework fixes an error and is part of Correction.",""],bookRef:"Book p. 117"},{id:"sv-1-1286",phase:1,topic:"1.4.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Waste is any activity that consumes resources without adding [?] for the customer.`,options:["capacity","cost","value","variation"],answer:2,hint:"Waste is defined from the customer’s point of view.",steps:[{title:"Key idea",body:"Muda is any activity that uses resources but adds no value the customer would pay for."},{title:"Eliminate look-alikes",body:"Waste adds cost and uses capacity; it does not add value."}],final:"value → answer **C**",whyWrong:["Incorrect — waste is defined by value, not capacity.","Incorrect — waste adds cost; the missing word is what it fails to add.","","Incorrect — variation is the focus of Six Sigma, not the definition of waste."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1287",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:3,stem:"Which waste name is NOT used in the syllabus 1.4.4 list, even though it describes one of the seven elements?",options:["Conveyance","Inventory","Transportation","Waiting"],answer:2,hint:"The syllabus uses its own words; the eight-waste list renames three of them.",steps:[{title:"Key idea",body:"Transportation is the DOWNTIME name for the syllabus element Conveyance."},{title:"Eliminate look-alikes",body:"Conveyance, Inventory and Waiting all appear exactly as written in topic 1.4.4."}],final:"Transportation is a DOWNTIME name → answer **C**",whyWrong:["Incorrect — Conveyance is the syllabus 1.4.4 term.","Incorrect — Inventory is a syllabus 1.4.4 term.","","Incorrect — Waiting is a syllabus 1.4.4 term."],trap:"Defects, Transportation and Extra-processing are eight-waste names.",bookRef:"Syllabus 1.4.4"},{id:"sv-1-1288",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:2,stem:"All of the following are examples of **Correction** EXCEPT:",options:["A second manager signature on every standard order","A repeat truck roll after a failed first repair","A credit note issued for a billing error","A support ticket reopened because the fault returned"],answer:0,hint:"Correction needs an error. Which option has none?",steps:[{title:"Key idea",body:"Correction is effort caused by an error."},{title:"Apply to the stem",body:"The extra signature is applied to a correct order — that is Overprocessing."}],final:"Extra signature = Overprocessing → answer **A**",whyWrong:["","Incorrect — a repeat visit to fix a failed job is Correction.","Incorrect — work to fix a billing error is Correction.","Incorrect — reopened work caused by an error is Correction."],bookRef:"Book p. 502"},{id:"sv-1-1289",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:1,stem:"All of the following are examples of **Inventory** EXCEPT:",options:["Three hundred orders waiting to be scheduled","A technician idle on site until the port is activated","Spare parts stocked well beyond current demand","A shared mailbox holding 1,200 unprocessed claims"],answer:1,hint:"Inventory is a quantity held; which option is a person’s idle time?",steps:[{title:"Key idea",body:"Inventory = stock, WIP or information held beyond need."},{title:"Apply to the stem",body:"An idle technician is a person waiting → Waiting."}],final:"Idle technician = Waiting → answer **B**",whyWrong:["Incorrect — queued orders held in the system are Inventory.","","Incorrect — stock beyond need is Inventory.","Incorrect — unprocessed information piling up is Inventory."],bookRef:"Book p. 502"},{id:"sv-1-1290",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:1,stem:"Which is NOT an example of **Conveyance**?",options:["A router shipped warehouse → hub → depot → van","Blood samples carried in batches to a distant lab","An engineer reaching across the bench for a meter","A claim file emailed back and forth between two offices"],answer:2,hint:"Conveyance moves items; which option moves a person within the workstation?",steps:[{title:"Key idea",body:"Conveyance = materials, products or information moving between locations."},{title:"Apply to the stem",body:"Reaching across a bench is a person moving locally → Motion."}],final:"Reaching = Motion → answer **C**",whyWrong:["Incorrect — goods routed through several locations is Conveyance.","Incorrect — material moved between locations is Conveyance.","","Incorrect — information moved between locations is Conveyance."],bookRef:"Book p. 502"},{id:"sv-1-1291",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:2,stem:"Which is NOT a typical countermeasure for **Waiting**?",options:["Balancing workload across process steps","Synchronising hand-offs between teams","Pre-approving standard, low-risk changes","Adding a final inspection step before release"],answer:3,hint:"Which option adds a step instead of removing idle time?",steps:[{title:"Key idea",body:"Waiting fixes: balance load, synchronise hand-offs, pre-approve standard work."},{title:"Apply to the stem",body:"An extra inspection adds time and is a Correction-related check, not a Waiting fix."}],final:"Inspection does not cut Waiting → answer **D**",whyWrong:["Incorrect — balancing load removes idle time at starved steps.","Incorrect — synchronised hand-offs remove idle gaps.","Incorrect — pre-approval removes waiting for an approval board.",""],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1292",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:1,stem:"All of the following are signs of **Overproduction** EXCEPT:",options:["Each order needs three approvals although one is enough","Reports are printed every week that nobody reads","Finished units pile up ahead of customer orders","Paper statements are mailed to customers who receive e-bills"],answer:0,hint:"Overproduction is extra output; which option is extra effort per item?",steps:[{title:"Key idea",body:"Overproduction = more, or earlier, output than needed."},{title:"Apply to the stem",body:"Three approvals on one order is extra work per item → Overprocessing."}],final:"Extra approvals = Overprocessing → answer **A**",whyWrong:["","Incorrect — output nobody asked for is Overproduction.","Incorrect — producing ahead of demand is Overproduction.","Incorrect — output the customer does not need is Overproduction."],bookRef:"Book p. 502"},{id:"sv-1-1293",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:3,stem:"Which syllabus 1.4.4 element does NOT change its name in the eight-waste (DOWNTIME) list?",options:["Conveyance","Correction","Motion","Overprocessing"],answer:2,hint:"Three of the seven are renamed; the rest keep their names.",steps:[{title:"Key idea",body:"Renamed: Correction → Defects, Conveyance → Transportation, Overprocessing → Extra-processing."},{title:"Apply to the stem",body:"Motion keeps its name in both lists."}],final:"Motion keeps its name → answer **C**",whyWrong:["Incorrect — Conveyance becomes Transportation.","Incorrect — Correction becomes Defects.","","Incorrect — Overprocessing becomes Extra-processing."],bookRef:"Syllabus p. 2"},{id:"sv-1-1294",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:2,stem:"On a hospital ward, dressings are used every hour, but they are kept in a central store room at the far end of the corridor. Nurses walk there and back several times per shift. Which waste is this?",options:["Conveyance","Inventory","Motion","Waiting"],answer:2,hint:"Who is moving — a person or an item?",steps:[{title:"Key idea",body:"A person moving unnecessarily within the workplace is Motion, however far they walk."},{title:"Apply to the stem",body:"Nurses walk to fetch supplies used hourly → Motion; fix with point-of-use storage."}],final:"Walking nurses = Motion → answer **C**",whyWrong:["Incorrect — the nurse (a person) is moving within the workplace; Conveyance is items moving between locations.","Incorrect — the problem is the walking, not the quantity of dressings held.","","Incorrect — the nurses are moving, not idle."],bookRef:"Book p. 502"},{id:"sv-1-1295",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:1,stem:"A machining cell polishes every internal bore to a mirror finish. The drawing and the customer accept a standard machined finish, and the bore is hidden after assembly. Which waste is the polishing?",options:["Correction","Overprocessing","Overproduction","Motion"],answer:1,hint:"Compare the work done with what the customer requires.",steps:[{title:"Key idea",body:"Working to a higher standard than the customer needs is Overprocessing."},{title:"Eliminate look-alikes",body:"No error (Correction) and no extra quantity (Overproduction)."}],final:"Mirror finish not required = Overprocessing → answer **B**",whyWrong:["Incorrect — the bores are not defective; nothing is being fixed.","","Incorrect — the quantity is correct; the extra is effort per part.","Incorrect — the waste is the extra work, not operator movement."],bookRef:"Book p. 502"},{id:"sv-1-1296",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:3,stem:"Product owners ask a software team to build every feature “just in case” a customer wants it. Usage data later show that 40% of the delivered features are never used. Which waste is MOST evident?",options:["Overprocessing","Inventory","Overproduction","Correction"],answer:2,hint:"Were the items needed at all, or were needed items over-worked?",steps:[{title:"Key idea",body:"Making output nobody asked for is Overproduction."},{title:"Apply to the stem",body:"Unused features are whole outputs produced without demand."},{title:"Eliminate look-alikes",body:"Overprocessing would be gold-plating a feature that is needed."}],final:"Unneeded features = Overproduction → answer **C**",whyWrong:["Incorrect — Overprocessing is extra effort on a needed item; here whole unneeded items were built.","Incorrect — the features are delivered, not sitting as unreleased work-in-progress.","","Incorrect — the features work; no error is being fixed."],trap:"Gold-plating a needed feature = Overprocessing; building unneeded features = Overproduction.",bookRef:"Book p. 502"},{id:"sv-1-1297",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:1,stem:"A broadband repair fails, and a second technician must be sent to the same customer two days later to finish the job. Which waste does the second visit represent?",options:["Conveyance","Correction","Overprocessing","Waiting"],answer:1,hint:"Repeat work exists because something went wrong.",steps:[{title:"Key idea",body:"Repeat visits and rework caused by errors are Correction."},{title:"Eliminate look-alikes",body:"Overprocessing applies only to items already done right."}],final:"Repeat visit = Correction → answer **B**",whyWrong:["Incorrect — the visit exists because of a failed job, not unnecessary transport of goods.","","Incorrect — the first job was not done right, so this is fixing, not extra work on a good item.","Incorrect — the waste is the repeat work, not idle time."],bookRef:"Book p. 502"},{id:"sv-1-1298",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:2,stem:"In a distribution centre, incoming pallets go from the receiving dock to a temporary bay, then to the main racking, then to a picking zone, and finally to the dispatch dock. Which waste does the repeated moving of pallets show?",options:["Motion","Inventory","Overproduction","Conveyance"],answer:3,hint:"What is moving — material or people — and where?",steps:[{title:"Key idea",body:"Materials moved between locations more than necessary (double handling) is Conveyance."},{title:"Apply to the stem",body:"Five locations and four moves for one pallet → Conveyance; fix with direct routing."}],final:"Double handling = Conveyance → answer **D**",whyWrong:["Incorrect — the pallets (materials) are moving between locations; Motion is people moving within a workstation.","Incorrect — the waste described is the moving, not the quantity stored.","Incorrect — nothing is made ahead of demand.",""],bookRef:"Book p. 502"},{id:"sv-1-1299",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:1,stem:"Shop staff cannot activate new SIM cards while the activation system runs its hourly batch, so customers and staff stand idle for up to 20 minutes. Which waste is this?",options:["Waiting","Inventory","Motion","Overprocessing"],answer:0,hint:"People idle because the upstream system is not ready.",steps:[{title:"Key idea",body:"Idle people or work because an input is not ready is Waiting."},{title:"Eliminate look-alikes",body:"No quantity build-up, no movement, no extra work."}],final:"Idle until batch completes = Waiting → answer **A**",whyWrong:["","Incorrect — the stem describes idle people, not a quantity of stock.","Incorrect — nobody is moving unnecessarily.","Incorrect — no extra work is done on each activation."],bookRef:"Book p. 502"},{id:"sv-1-1300",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:3,stem:"A testing laboratory always has about **140** samples logged but not yet tested. The quality manager asks the Black Belt to describe this queue of samples in terms of the seven wastes. Which waste BEST describes the queue itself?",options:["Waiting","Inventory","Correction","Conveyance"],answer:1,hint:"Two views of one queue: item quantity or idle time?",steps:[{title:"Key idea",body:"From the work item’s point of view a queue is Inventory (WIP)."},{title:"Apply to the stem",body:"The stem counts 140 samples held → Inventory."},{title:"Eliminate look-alikes",body:"Waiting would fit a stem about the testers or customers being idle."}],final:"Queue counted as items = Inventory → answer **B**",whyWrong:["Incorrect — Waiting would describe idle people or customers; the stem counts samples held in the system.","","Incorrect — the samples are not being re-tested because of errors.","Incorrect — the samples are not described as moving between locations."],trap:"“Samples are queued” → Inventory; “the analyst is idle until…” → Waiting.",bookRef:"Book p. 502"},{id:"sv-1-1301",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:3,stem:"A line keeps running ahead of orders. Piles of work-in-progress sit between steps, forklifts move the piles to overflow storage and back, and defects are found weeks later when the stock is used. Which waste should the Black Belt see as the ROOT of the others?",options:["Inventory","Conveyance","Overproduction","Correction"],answer:2,hint:"Which waste is often called the worst because it generates the others?",steps:[{title:"Key idea",body:"Overproduction creates Inventory, extra Conveyance and hides defects until later."},{title:"Apply to the stem",body:"Running ahead of orders is the source; the other three follow from it."}],final:"Root waste = Overproduction → answer **C**",whyWrong:["Incorrect — the piles are a result of producing ahead of orders.","Incorrect — the forklift moves exist only because extra output must be stored.","","Incorrect — late-found defects are hidden by the excess output, not its cause."],bookRef:"Book p. 502"},{id:"sv-1-1302",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:2,stem:"A cable assembly line holds large piles of parts between stations, so problems stay hidden and lead time is long. The Black Belt wants a Lean method the book names as the best inventory-control method for attacking several of the seven wastes. Which method is this?",options:["5S","Kaizen","Kanban","Poka-yoke"],answer:2,hint:"Which Lean tool controls how much material is released?",steps:[{title:"Key idea",body:"Book p. 511: kanban is the best inventory-control method to attack several of the seven wastes."},{title:"Eliminate look-alikes",body:"5S organises, kaizen improves generally, poka-yoke prevents errors."}],final:"Kanban for Inventory → answer **C**",whyWrong:["Incorrect — 5S organises the workplace; the book names kanban for inventory control.","Incorrect — kaizen is continuous improvement in general, not an inventory-control method.","","Incorrect — poka-yoke prevents errors (Correction), not excess stock."],bookRef:"Book p. 511"},{id:"sv-1-1303",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:3,stem:"Experienced network engineers spend hours copying data between spreadsheets. Their ideas for simple automation are never asked for. A trainer asks how this fits the syllabus waste lists. Which answer is BEST?",options:["It is Motion, because the engineers move data between screens","It is Overprocessing, which the eight-waste list calls Non-utilized talent","It is Waiting, because the engineers are waiting for permission","It is Non-utilized talent, which is in the eight-waste list but not one of the seven elements"],answer:3,hint:"Unused skills and ideas belong to the eighth waste.",steps:[{title:"Key idea",body:"Non-utilized talent = not using people’s skills, knowledge and ideas."},{title:"Apply to the stem",body:"It is a real waste, but topic 1.4.4 lists only seven elements and it is not one of them."}],final:"Non-utilized talent — eight-waste list only → answer **D**",whyWrong:["Incorrect — the point of the stem is unused skills and ideas, not movement.","Incorrect — the eight-waste name for Overprocessing is Extra-processing.","Incorrect — the engineers are busy, not idle; their talent is unused.",""],bookRef:"Syllabus p. 2"},{id:"sv-1-1304",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:2,stem:"A Black Belt is asked to “cut waste” in a claims process she has never seen. What is the FIRST action she should take?",options:["Walk and map the current process and name the wastes she observes","Install a kanban system between every pair of steps","Set a target to remove 50% of all waste in three months","Buy workflow software to automate the existing steps"],answer:0,hint:"The book says what comes before elimination.",steps:[{title:"Key idea",body:"Book p. 502: identifying waste is the first step toward eliminating it."},{title:"Eliminate look-alikes",body:"Kanban, targets and software are later decisions."}],final:"Identify the waste first → answer **A**",whyWrong:["","Incorrect — choosing a solution before identifying the waste skips the first step.","Incorrect — a target without knowing the waste has no basis.","Incorrect — automating unexamined steps can automate the waste."],bookRef:"Book p. 502"},{id:"sv-1-1305",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:3,stem:"Twelve per cent of service tickets are reopened. To reduce Correction, the Black Belt adds a second checker who reviews every ticket before closure. Was this an appropriate action, and why?",options:["Yes, because inspection is the most reliable way to remove Correction","Yes, because every waste should be met with an extra control step","No, because inspection is non-value-added and does not remove the root causes of errors","No, because reopened tickets are Inventory, not Correction"],answer:2,hint:"Prevention versus detection.",steps:[{title:"Key idea",body:"Correction falls when errors are prevented (root causes, mistake-proofing), not when more checkers are added."},{title:"Apply to the stem",body:"The second checker adds a non-value-added step while the errors continue."}],final:"Not appropriate — prevent, don’t inspect → answer **C**",whyWrong:["Incorrect — inspection detects errors after they happen; it does not remove their cause.","Incorrect — extra control steps are often waste themselves.","","Incorrect — reopened work caused by errors is Correction."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1306",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:2,stem:"Tickets bounce between the service desk and three resolver groups before anyone fixes them. In her waste-walk report, the Black Belt labels this **Motion**. Was this appropriate, and why?",options:["Yes, because any movement in a process is Motion","Yes, because tickets are moved by people clicking","No, because the tickets are waiting, so it is Waiting","No, because information moving between teams is Conveyance"],answer:3,hint:"What is moving, and where?",steps:[{title:"Key idea",body:"Motion = people moving within the workstation. Conveyance = items or information moving between locations or teams."},{title:"Apply to the stem",body:"Tickets passed between groups → Conveyance, so the label is wrong."}],final:"Not appropriate — it is Conveyance → answer **D**",whyWrong:["Incorrect — the seven elements separate Motion from Conveyance.","Incorrect — the clicking is incidental; the waste is the item travelling between teams.","Incorrect — the stem describes repeated transfer, not idle time.",""],bookRef:"Book p. 502"},{id:"sv-1-1307",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:2,stem:"A Black Belt’s audit sheet records observations under “Defects”. The Black Belt’s report must use the seven syllabus elements, so she lists these observations under **Correction**. Was this appropriate, and why?",options:["Yes, because Defects is the eight-waste name for the syllabus element Correction","Yes, because Defects and Correction are both names for Overprocessing","No, because Defects should be listed under Non-utilized talent","No, because Defects has no match among the seven elements"],answer:0,hint:"Map each DOWNTIME name to its syllabus element.",steps:[{title:"Key idea",body:"Eight-waste renames: Defects → Correction, Transportation → Conveyance, Extra-processing → Overprocessing."},{title:"Apply to the stem",body:"Listing “Defects” under Correction is the right mapping."}],final:"Appropriate — Defects ↔ Correction → answer **A**",whyWrong:["","Incorrect — Overprocessing corresponds to Extra-processing, not Defects.","Incorrect — Non-utilized talent is about unused skills, not errors.","Incorrect — Defects maps directly to Correction."],bookRef:"Syllabus p. 2"},{id:"sv-1-1308",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:2,stem:"Every expense claim, even under 20 OMR, needs signatures from three managers. Audit data show no low-value claim has been rejected in two years. Which is the BEST action for the Black Belt to recommend?",options:["Add a fourth signature to make the control stronger","Match the approval effort to the risk and remove signatures that add nothing","Batch the claims weekly so managers sign them together","Train managers to sign faster"],answer:1,hint:"Extra approvals beyond the need are a named waste.",steps:[{title:"Key idea",body:"Approvals beyond what the risk or customer requires are Overprocessing."},{title:"Apply to the stem",body:"The data show the signatures change nothing, so reduce them."}],final:"Remove unneeded approvals → answer **B**",whyWrong:["Incorrect — more signatures add more Overprocessing.","","Incorrect — batching adds Waiting and Inventory without removing the extra work.","Incorrect — signing faster keeps the unnecessary work."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1309",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:3,stem:"A project cut Waiting in an order process by removing a weekly approval board. Six months later the board has quietly returned and lead time is back to its old level. What should the team have done to prevent this?",options:["Measured the baseline again before closing the project","Repeated the waste walk to find more wastes","Used Lean tools such as standard work and visual controls to hold the gains","Moved the approval board to a different day of the week"],answer:2,hint:"The book warns that wastes can return.",steps:[{title:"Key idea",body:"Book p. 503: removed wastes can return if Lean tools are not used to sustain the gains."},{title:"Apply to the stem",body:"Standard work, visual controls and audits keep the new way in place."}],final:"Sustain with Lean tools → answer **C**",whyWrong:["Incorrect — re-measuring the baseline does not stop the old practice returning.","Incorrect — more waste walks find waste; they do not sustain the removal.","","Incorrect — moving the board keeps the Waiting."],bookRef:"Book p. 503"},{id:"sv-1-1310",phase:1,topic:"1.4.4",qtype:"best-action",difficulty:2,stem:"A Black Belt has found all seven wastes in a provisioning process and has data on the minutes each one costs per order. Her team is small. Which is the BEST way to proceed?",options:["Attack all seven wastes at the same time","Start with Motion because it is the easiest waste to see","Wait until the Control phase to address the wastes","Rank the wastes by their measured impact and tackle the largest first"],answer:3,hint:"Let the data set the priority.",steps:[{title:"Key idea",body:"Naming wastes turns a vague problem into specific opportunities, which the team then prioritises with data."},{title:"Eliminate look-alikes",body:"Doing everything, the easiest, or nothing until Control are weaker choices."}],final:"Prioritise by measured impact → answer **D**",whyWrong:["Incorrect — spreading a small team across all seven dilutes effort.","Incorrect — visibility is not impact; the data should decide.","Incorrect — waste is attacked during the project, not deferred to Control.",""],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1311",phase:1,topic:"1.4.4",qtype:"output",difficulty:1,stem:`A Gemba walk in a repair centre classifies **240** waste observations:

\`\`\`
Pareto Chart of Waste type

Waste type       Count  Percent  Cum %
Waiting             84     35.0   35.0
Correction          60     25.0   60.0
Motion              36     15.0   75.0
Conveyance          24     10.0   85.0
Overprocessing      18      7.5   92.5
Inventory           12      5.0   97.5
Overproduction       6      2.5  100.0
\`\`\`

Which conclusion is supported by the output?`,options:["Waiting and Correction together account for 60% of the observations","Motion is the largest single waste category","Inventory accounts for 15% of the observations","Overproduction should be ignored because it is the smallest category"],answer:0,hint:"Read the Cum % column at the second bar.",steps:[{title:"Key idea",body:"A Pareto output lists categories largest first with a cumulative percentage."},{title:"Apply to the stem",body:"Cum % after Correction = 60.0, so Waiting + Correction = 60%."}],final:"Cum % after two bars = 60.0 → answer **A**",whyWrong:["","Incorrect — Motion is third (15%); Waiting is the largest.","Incorrect — 15% is Motion; Inventory is 5%.","Incorrect — a small count is lower priority, but not proof it is harmless."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1312",phase:1,topic:"1.4.4",qtype:"output",difficulty:2,stem:`A Black Belt times 50 orders through a fulfilment process:

\`\`\`
Descriptive Statistics: Minutes per order

Variable       N   Mean  StDev  Median
Touch time    50   22.4    4.1    22.0
Queue time    50  615.0  142.0   598.0
Rework time   50    9.8    6.3     8.5
\`\`\`

Which waste does the output show to be the MAIN contributor to lead time?`,options:["Correction, because rework time has the largest standard deviation","Waiting, because queue time is far larger than touch time","Overprocessing, because touch time is above 20 minutes","Motion, because touch time varies from order to order"],answer:1,hint:"Compare the printed means.",steps:[{title:"Key idea",body:"Time an order spends queued, with no one working on it, is Waiting."},{title:"Apply to the stem",body:"Queue time mean 615.0 vs touch 22.4 and rework 9.8 → Waiting dominates."}],final:"Queue time dominates → Waiting → answer **B**",whyWrong:["Incorrect — rework has the smallest mean and its StDev is not the largest; queue time dominates.","","Incorrect — touch time is the working time and is small next to queue time.","Incorrect — nothing in the output measures movement."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1313",phase:1,topic:"1.4.4",qtype:"output",difficulty:2,stem:`A service manager compares ticket reopen rates by team:

\`\`\`
Tabulated Statistics: Team, Reopened

Team      No    Yes   All   %Yes
Access   470     30   500    6.0
Core     378     22   400    5.5
Field    395    105   500   21.0
All     1243    157  1400   11.2
\`\`\`

Which conclusion is BEST supported?`,options:["Inventory is concentrated in the Field team, because it has the most tickets","All three teams show similar levels of Correction","Correction is concentrated in the Field team, so root-cause work should start there","The Core team has the highest reopen rate"],answer:2,hint:"Reopened work is a sign of which waste? Then read %Yes.",steps:[{title:"Key idea",body:"Reopened tickets are repeat work caused by errors → Correction."},{title:"Apply to the stem",body:"Field %Yes = 21.0, against 6.0 and 5.5 → focus there."}],final:"Field 21.0% → Correction hotspot → answer **C**",whyWrong:["Incorrect — reopened tickets are Correction, and Field ties with Access on volume.","Incorrect — Field’s 21.0% is far above 6.0% and 5.5%.","","Incorrect — Core has the lowest rate, 5.5%."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1314",phase:1,topic:"1.4.4",qtype:"output",difficulty:2,stem:`A depot reviews its spare-part stock:

\`\`\`
Descriptive Statistics: Days of supply by Part

Part                 N   Mean
Fibre patch cords   12   25.0
ONT units           12   30.0
Splice trays        12   45.0
Legacy DSL modems   12  420.0
\`\`\`

Legacy DSL modems are no longer sold. Which conclusion is BEST supported?`,options:["ONT units show the clearest Inventory waste","Legacy DSL modems show the clearest Overprocessing waste","Fibre patch cords show the clearest Conveyance waste","Legacy DSL modems show the clearest Inventory waste"],answer:3,hint:"Days of supply far beyond need = stock held beyond need.",steps:[{title:"Key idea",body:"Stock beyond current need is Inventory."},{title:"Apply to the stem",body:"Legacy modems: 420.0 days of an unsold product, against 25–45 days for the others."}],final:"Legacy modems 420.0 days → Inventory → answer **D**",whyWrong:["Incorrect — ONT units hold about 30 days, close to the other current parts.","Incorrect — excess stock is Inventory; no extra work per item is shown.","Incorrect — the output measures stock levels, not movement.",""],bookRef:"Book p. 502"},{id:"sv-1-1315",phase:1,topic:"1.4.4",qtype:"output",difficulty:3,stem:`A service desk counts how many times each ticket was passed between resolver groups:

\`\`\`
Tally for Discrete Variables: Hand-offs per ticket

Hand-offs   Count  Percent
0             820    41.00
1             560    28.00
2             380    19.00
3 or more     240    12.00
N=           2000
\`\`\`

Which statement is CORRECT?`,options:["12% of tickets were passed on three or more times, a strong sign of Conveyance","12% of tickets were passed on three or more times, a strong sign of Motion","41% of tickets show Conveyance, because they had no hand-offs","28% of tickets show Correction, because they had one hand-off"],answer:0,hint:"Hand-offs are information travelling between teams.",steps:[{title:"Key idea",body:"Repeated hand-offs of a ticket between teams are Conveyance."},{title:"Apply to the stem",body:"The “3 or more” row prints 12.00%."},{title:"Eliminate look-alikes",body:"Same number, wrong waste (Motion) is the trap."}],final:"3+ hand-offs = 12% → Conveyance → answer **A**",whyWrong:["","Incorrect — tickets moving between groups is Conveyance, not people moving at a workstation.","Incorrect — tickets with zero hand-offs did not travel at all.","Incorrect — a hand-off is movement of information, not the fixing of an error."],trap:"Hand-offs move information → Conveyance, not Motion.",bookRef:"Book p. 502"},{id:"sv-1-1316",phase:1,topic:"1.4.4",qtype:"output",difficulty:3,stem:`A Black Belt reviews approvals on standard purchase orders:

\`\`\`
Descriptive Statistics: Signatures per order by Value band

Value band        N   Mean  Minimum  Maximum
Under 100 OMR   210   3.00        3        3
100-1000 OMR    140   3.00        3        3
Over 1000 OMR    50   3.10        3        4
\`\`\`

The policy says only orders over 1,000 OMR need more than one signature. Which waste does the output reveal?`,options:["Overproduction, because 210 low-value orders were raised","Overprocessing, because low-value orders receive the same three signatures as high-value ones","Correction, because some high-value orders needed a fourth signature","Waiting, because the maximum number of signatures is 4"],answer:1,hint:"Compare the printed signatures with what the policy requires.",steps:[{title:"Key idea",body:"Approvals beyond what the requirement calls for are Overprocessing."},{title:"Apply to the stem",body:"Under 100 OMR: mean 3.00, minimum 3 — every low-value order gets three signatures where one is enough."}],final:"Three signatures where one is needed → Overprocessing → answer **B**",whyWrong:["Incorrect — the number of orders reflects demand; the waste is the extra work per order.","","Incorrect — a fourth signature is not shown to fix an error.","Incorrect — the output counts signatures, not idle time."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-1317",phase:1,topic:"1.4.4",qtype:"true-false",difficulty:2,stem:"Waiting is one of the wastes that keeps the same name in the syllabus seven elements and in the eight-waste (DOWNTIME) list. True or False?",options:["True","False"],answer:0,hint:"Which three of the seven are renamed?",steps:[{title:"Key idea",body:"Renamed: Correction (Defects), Conveyance (Transportation), Overprocessing (Extra-processing)."},{title:"Apply to the stem",body:"Waiting is not among them, so it keeps its name."}],final:"Waiting is unchanged → **True** (answer **A**)",whyWrong:["","Incorrect — Waiting is the “W” in DOWNTIME, unchanged."],bookRef:"Syllabus p. 2"},{id:"sv-1-1318",phase:1,topic:"1.4.4",qtype:"true-false",difficulty:1,stem:"In the seven elements of waste, Conveyance refers to people walking unnecessarily within their own work area. True or False?",options:["True","False"],answer:1,hint:"Separate people moving locally from items moving between places.",steps:[{title:"Key idea",body:"Conveyance = materials, products or information moving between locations."},{title:"Apply to the stem",body:"People walking within their work area is Motion, so the statement is false."}],final:"That is Motion → **False** (answer **B**)",whyWrong:["Incorrect — people moving within the work area is Motion.",""],bookRef:"Book p. 502"},{id:"sv-1-1319",phase:1,topic:"1.4.4",qtype:"true-false",difficulty:3,stem:"Producing a batch earlier than the next step needs it is Overproduction, even when the quantity is exactly right. True or False?",options:["True","False"],answer:0,hint:"Overproduction = too many OR too soon.",steps:[{title:"Key idea",body:"Overproduction is making more, or earlier, than the next step needs."},{title:"Apply to the stem",body:"Right quantity but too early still counts."}],final:"Too soon is Overproduction → **True** (answer **A**)",whyWrong:["","Incorrect — Overproduction covers timing (too soon) as well as quantity."],bookRef:"Book p. 502"},{id:"sv-1-1320",phase:1,topic:"1.4.4",qtype:"true-false",difficulty:3,stem:"A record-keeping step that the customer would not pay for, but that regulation requires, should be deleted at once because it is waste. True or False?",options:["True","False"],answer:1,hint:"Some non-value-added steps cannot be removed yet.",steps:[{title:"Key idea",body:"Steps required by regulation or the business are business value-added: keep them lean, but keep them."},{title:"Apply to the stem",body:"Deleting a required step is not the right response."}],final:"Business value-added → minimise, not delete → **False** (answer **B**)",whyWrong:["Incorrect — a required step is business value-added; it is minimised, not deleted.",""],bookRef:"Book p. 117"},{id:"sv-1-1321",phase:1,topic:"1.4.4",qtype:"sequence",difficulty:3,stem:`A line overproduces. Put the knock-on effects in the order they typically occur:

- **P** Extra units are made ahead of orders
- **Q** Defects in the stored units are found weeks later when they are used
- **R** The extra units are stored as stock
- **S** The stock is moved to overflow storage and back`,options:["P → S → R → Q","R → P → S → Q","P → R → S → Q","P → Q → R → S"],answer:2,hint:"Overproduction → Inventory → Conveyance → hidden Correction.",steps:[{title:"Key idea",body:"Overproduction creates Inventory, which must be moved (Conveyance), and it hides defects until later (Correction)."},{title:"Apply to the stem",body:"P (make) → R (store) → S (move) → Q (defects found)."}],final:"P → R → S → Q → answer **C**",whyWrong:["Incorrect — units must be stored as stock before they are moved to overflow storage.","Incorrect — stock cannot exist before the extra units are made.","","Incorrect — defects surface last, when the stored units are finally used."],bookRef:"Book p. 502"},{id:"sv-1-1322",phase:1,topic:"1.4.4",qtype:"sequence",difficulty:2,stem:`Put the steps for tackling waste in a process in the correct order:

- **P** Sustain the gains with Lean tools such as standard work and visual controls
- **Q** Identify and name the wastes in the current process
- **R** Apply a countermeasure to the root cause
- **S** Find the root cause of the priority waste`,options:["Q → R → S → P","S → Q → R → P","Q → S → P → R","Q → S → R → P"],answer:3,hint:"Identify → understand → fix → hold.",steps:[{title:"Key idea",body:"Book p. 502–503: identifying waste is the first step; wastes return unless Lean tools hold the gains."},{title:"Apply to the stem",body:"Q identify → S root cause → R countermeasure → P sustain."}],final:"Q → S → R → P → answer **D**",whyWrong:["Incorrect — a countermeasure needs the root cause first.","Incorrect — the waste must be identified before its root cause is sought.","Incorrect — gains are sustained after the countermeasure is applied.",""],bookRef:"Book pp. 502–503"},{id:"sv-1-1323",phase:1,topic:"1.4.4",qtype:"sequence",difficulty:2,stem:`Put these four wastes in the order they appear in the **DOWNTIME** mnemonic:

- **P** Inventory
- **Q** Waiting
- **R** Defects
- **S** Transportation`,options:["R → Q → S → P","R → S → Q → P","Q → R → S → P","R → Q → P → S"],answer:0,hint:"Spell it: D-O-W-N-T-I-M-E.",steps:[{title:"Key idea",body:"DOWNTIME = Defects, Overproduction, Waiting, Non-utilized talent, Transportation, Inventory, Motion, Extra-processing."},{title:"Apply to the stem",body:"D (R) → W (Q) → T (S) → I (P)."}],final:"R → Q → S → P → answer **A**",whyWrong:["","Incorrect — Waiting (W) comes before Transportation (T).","Incorrect — Defects (D) is the first letter.","Incorrect — Transportation (T) comes before Inventory (I)."],bookRef:"Syllabus p. 2"},{id:"sv-1-1324",phase:1,topic:"1.4.4",qtype:"sequence",difficulty:2,stem:`A Black Belt uses the book’s “re-” hint on a process map. Put her analysis in order:

- **P** Remove or reduce the step if it adds no value
- **Q** Mark steps whose names start with “re-” as likely waste
- **R** Name the waste using the syllabus term
- **S** Check each marked step against the value tests (form, fit, function; customer would pay)`,options:["S → Q → R → P","Q → S → R → P","Q → R → S → P","Q → S → P → R"],answer:1,hint:"Flag → test → name → act.",steps:[{title:"Key idea",body:"Book p. 117: steps beginning with “re-” are usually waste; the value tests confirm it."},{title:"Apply to the stem",body:"Q flag → S test → R name → P remove or reduce."}],final:"Q → S → R → P → answer **B**",whyWrong:["Incorrect — the steps are marked first, then tested.","","Incorrect — confirm the step is waste with the value tests before naming it.","Incorrect — name the waste before acting, so the right countermeasure is chosen."],bookRef:"Book p. 117"},{id:"sv-1-1325",phase:1,topic:"1.4.5",qtype:"concept",difficulty:1,stem:"In the 5S sequence, which step comes immediately after **Straighten**?",options:["Sort","Standardize","Shine","Self-Discipline"],answer:2,hint:"Sort → Straighten → Shine → Standardize → Self-Discipline.",steps:[{title:"Key idea",body:"Syllabus order: Sort, Straighten, Shine, Standardize, Self-Discipline."},{title:"Apply to the stem",body:"The step after Straighten (2nd) is Shine (3rd)."}],final:"Straighten → Shine → answer **C**",whyWrong:["Incorrect — Sort is the first step and comes before Straighten.","Incorrect — Standardize is the fourth step, after Shine.","","Incorrect — Self-Discipline is the fifth and last step."],bookRef:"Book pp. 503–504"},{id:"sv-1-1326",phase:1,topic:"1.4.5",qtype:"concept",difficulty:1,stem:"What is the main purpose of the **Sort** step in 5S?",options:["To give every needed item a labelled, designated place","To clean the area and find the sources of mess","To set visual rules that keep the area organised","To remove everything not needed for the current work"],answer:3,hint:"Sort decides what stays.",steps:[{title:"Key idea",body:"Sort keeps only the essentials and removes everything else (book p. 504)."},{title:"Eliminate look-alikes",body:"Place = Straighten; clean = Shine; rules = Standardize."}],final:"Sort = remove the unneeded → answer **D**",whyWrong:["Incorrect — giving items a place is Straighten.","Incorrect — cleaning and mess prevention is Shine.","Incorrect — visual rules are Standardize.",""],bookRef:"Book p. 504"},{id:"sv-1-1327",phase:1,topic:"1.4.5",qtype:"concept",difficulty:2,stem:"According to the book, which items should a team start with when it begins the **Sort** step?",options:["The easiest items to decide on","The most expensive items in the area","The items used several times a day","The items owned by the area supervisor"],answer:0,hint:"The book’s advice on how to begin sorting.",steps:[{title:"Key idea",body:"Book p. 505: start Sort with the easiest items and discuss removal with everyone involved."},{title:"Eliminate look-alikes",body:"Cost, frequency and ownership are not the starting rule."}],final:"Start with the easiest items → answer **A**",whyWrong:["","Incorrect — the book advises starting with the easiest items, not the costliest.","Incorrect — frequently used items are kept; frequency guides storage, not the starting point.","Incorrect — ownership is not the book’s starting rule; removal is discussed with everyone."],bookRef:"Book p. 505"},{id:"sv-1-1328",phase:1,topic:"1.4.5",qtype:"concept",difficulty:3,stem:"A Black Belt plans to roll out new standardized work instructions in a cluttered depot. According to the book, what is the risk if 5S is not in place first?",options:["The instructions will make the depot’s Cpk fall below 1.33","The standardized work instructions will not create consistency","The instructions will replace the need for a control plan","The depot will have to repeat its Gage R&R study"],answer:1,hint:"Think of 5S as the base the other Lean tools stand on.",steps:[{title:"Key idea",body:"Book p. 513: without 5S, standardized work instructions will not create consistency."},{title:"Apply to the stem",body:"In a cluttered depot people cannot follow the same method, so the instructions will not stick."}],final:"No 5S → no consistency from standard work → answer **B**",whyWrong:["Incorrect — the book’s point is about consistency of work, not a capability value.","","Incorrect — instructions never replace a control plan; this is not the book’s warning.","Incorrect — measurement system analysis is unrelated to this 5S warning."],bookRef:"Book p. 513"},{id:"sv-1-1329",phase:1,topic:"1.4.5",qtype:"concept",difficulty:2,stem:"A team applies 5S to its weekly KPI dashboard. How is the **Sort** step applied?",options:["By fixing a layout so each KPI always appears in the same place","By clearing stale data and fixing the feeds that cause it","By removing charts and KPIs that nobody acts on","By agreeing a dashboard template that every team must use"],answer:2,hint:"Digital 5S follows the same five steps; Sort decides what stays.",steps:[{title:"Key idea",body:"Digital 5S: Sort keeps only the KPIs someone acts on; Straighten gives them a fixed layout."},{title:"Eliminate look-alikes",body:"Fixed layout = Straighten; clearing stale data = Shine; template = Standardize."}],final:"Remove unused KPIs = Sort → answer **C**",whyWrong:["Incorrect — a fixed place for each item is Straighten.","Incorrect — cleaning and fixing the source of mess is Shine.","","Incorrect — a common template is Standardize."],bookRef:"Book pp. 504–508"},{id:"sv-1-1330",phase:1,topic:"1.4.5",qtype:"concept",difficulty:2,stem:"Which statement about **Sort** and **Straighten** is CORRECT?",options:["Sort gives each item a shadow outline; Straighten removes unneeded items","Sort and Straighten are both sustaining actions","Sort and Straighten both rely mainly on 5S audits","Sort decides what stays in the area; Straighten decides where each item lives"],answer:3,hint:"What stays versus where it goes.",steps:[{title:"Key idea",body:"Sort removes the unneeded; Straighten gives every remaining item a labelled place."},{title:"Eliminate look-alikes",body:"Both are workplace actions; audits belong to Self-Discipline."}],final:"Sort = what stays; Straighten = where → answer **D**",whyWrong:["Incorrect — the steps are reversed: shadow outlines are Straighten, removal is Sort.","Incorrect — they are workplace actions; Standardize and Self-Discipline sustain.","Incorrect — audits support Self-Discipline, not the first two steps.",""],bookRef:"Book pp. 504–506"},{id:"sv-1-1331",phase:1,topic:"1.4.5",qtype:"concept",difficulty:2,stem:"Which statement about the **Straighten** step is CORRECT?",options:["Items shared by several people are kept in a central place everyone can reach","Every item is classified as useful, useless or unknown","Each zone of the area is assigned to a named person for cleaning","It is one of the two sustaining actions of 5S"],answer:0,hint:"Straighten answers “where does each item live?”.",steps:[{title:"Key idea",body:"Book p. 506: labels, floor tape, shadow outlines, items used together kept together, shared items in a central place."},{title:"Eliminate look-alikes",body:"Classification = Sort; named cleaners = Shine; sustaining = the last two S’s."}],final:"Shared items centrally = Straighten → answer **A**",whyWrong:["","Incorrect — that classification is the Sort method.","Incorrect — named cleaning zones belong to Shine.","Incorrect — Straighten is a workplace action; Standardize and Self-Discipline sustain."],bookRef:"Book p. 506"},{id:"sv-1-1332",phase:1,topic:"1.4.5",qtype:"statements",difficulty:2,stem:`Which statements about the **Sort** step are CORRECT?

1. Removal of items should be discussed with everyone involved.
2. Each remaining item is given a painted shadow outline.
3. Each zone of the area is given a named person for cleaning.
4. Benefits include a safer area and more space.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Sort removes the unneeded — carefully, and with the team.",steps:[{title:"Judge each statement",body:"**1** ✓ book p. 505. **2** ✗ shadow outlines belong to Straighten. **3** ✗ named cleaning zones belong to Shine. **4** ✓ book p. 505."},{title:"Match to a house pair",body:"Only statements 1 and 4 are correct, which is the option “1 and 4”."}],final:"Statements 1 and 4 describe Sort → answer **D**",whyWrong:["Incorrect — statement 2 is false: shadow outlines belong to Straighten.","Incorrect — statement 2 is false: shadow outlines belong to Straighten; statement 3 is false: named cleaning zones belong to Shine.","Incorrect — statement 3 is false: named cleaning zones belong to Shine.",""],bookRef:"Book p. 505"},{id:"sv-1-1333",phase:1,topic:"1.4.5",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Straighten cuts search time and walking, so it mainly attacks the wastes of Motion and [?].`,options:["Correction","Inventory","Overproduction","Waiting"],answer:3,hint:"What does a person do while a tool cannot be found?",steps:[{title:"Key idea",body:"A designated, labelled place for every item removes searching (Motion) and the idle time it causes (Waiting)."},{title:"Eliminate look-alikes",body:"Correction, Inventory and Overproduction are not what Straighten mainly removes."}],final:"Waiting → answer **D**",whyWrong:["Incorrect — Correction is fixing errors; finding items faster does not fix errors.","Incorrect — reducing stock is Sort or kanban territory, not the payoff of a labelled place.","Incorrect — Overproduction is making too much or too soon.",""],bookRef:"Book p. 506"},{id:"sv-1-1334",phase:1,topic:"1.4.5",qtype:"not-except",difficulty:2,stem:"All of the following are **Shine** activities EXCEPT:",options:["Cleaning equipment and the work area","Posting a photo of the correct bench layout for every shift","Tracing why dust builds up and stopping it at the source","Assigning each zone to a named person on a cleaning map"],answer:1,hint:"Shine cleans and prevents mess; which option sets a visual rule?",steps:[{title:"Key idea",body:"Shine = clean, find ways to keep it clean, prevent mess at its source (book pp. 504, 507)."},{title:"Apply to the stem",body:"A photo standard is a visual control → Standardize."}],final:"Photo standard = Standardize → answer **B**",whyWrong:["Incorrect — cleaning the area and equipment is the core of Shine.","","Incorrect — mess prevention at the source is the key idea of Shine.","Incorrect — a layout map of named cleaners removes “no man’s land” in Shine."],bookRef:"Book pp. 504–507"},{id:"sv-1-1335",phase:1,topic:"1.4.5",qtype:"scenario",difficulty:2,stem:"A year after a 5S event, the labels, floor markings and photo standards are all still in place. Yet the area is cluttered again because people have stopped following them, and nobody checks. Which S is weakest?",options:["Sort","Standardize","Self-Discipline","Straighten"],answer:2,hint:"Rules exist but nobody follows or checks them.",steps:[{title:"Key idea",body:"Standardize creates the rules; Self-Discipline is the habit of following them, kept alive by audits."},{title:"Apply to the stem",body:"Standards present, habit and checking absent → Self-Discipline."}],final:"Habit missing = Self-Discipline → answer **C**",whyWrong:["Incorrect — the problem is not deciding what to keep but keeping to the standard.","Incorrect — the standards exist; what is missing is the habit of following them.","","Incorrect — the places are still marked; people do not use them."],trap:"Rules missing → Standardize; rules ignored → Self-Discipline.",bookRef:"Book pp. 507–508"},{id:"sv-1-1336",phase:1,topic:"1.4.5",qtype:"scenario",difficulty:1,stem:"Field technicians walk back and forth across the depot several times a day looking for tools that have no fixed home. Which Lean method is the classic countermeasure for this waste of Motion?",options:["5S","Kanban","Poka-yoke","SMED"],answer:0,hint:"Which method gives everything a place and keeps it there?",steps:[{title:"Key idea",body:"Motion from searching and walking is classically attacked with 5S, especially Straighten."},{title:"Eliminate look-alikes",body:"Kanban = inventory; poka-yoke = errors; SMED = changeover time."}],final:"Searching and walking → 5S → answer **A**",whyWrong:["","Incorrect — kanban controls inventory levels, not where tools are kept.","Incorrect — poka-yoke prevents errors rather than organising the workplace.","Incorrect — SMED shortens changeovers; it is not the main fix for searching."],bookRef:"Book pp. 503–506"},{id:"sv-1-1337",phase:1,topic:"1.4.5",qtype:"best-action",difficulty:3,stem:"A team finishes Sort, Straighten and Shine in a pilot area in one week. The Black Belt declares 5S complete and moves the team to another project. Was this an appropriate action, and why?",options:["Yes, because the first three S’s are the only ones that change the workplace","Yes, because a pilot area only needs the workplace actions","No, because Standardize and Self-Discipline are needed to sustain the first three","No, because Shine must be repeated before Straighten is started"],answer:2,hint:"First three S’s = workplace actions; last two = sustaining actions.",steps:[{title:"Key idea",body:"Book p. 503: the first three S’s are workplace actions; the last two are sustaining actions."},{title:"Apply to the stem",body:"Without Standardize and Self-Discipline the area slides back, so stopping after three was not appropriate."}],final:"Not appropriate — the sustaining S’s are missing → answer **C**",whyWrong:["Incorrect — Standardize and Self-Discipline are still part of 5S; they hold the changes.","Incorrect — a pilot should prove the full method, including sustaining.","","Incorrect — the order Sort, Straighten, Shine was followed correctly."],bookRef:"Book pp. 503–508"},{id:"sv-1-1338",phase:1,topic:"1.4.5",qtype:"output",difficulty:3,stem:`A Black Belt compares installation time at two depots:

\`\`\`
Descriptive Statistics: Installation time (min)

Depot   N   Mean  StDev  Median  Minimum  Maximum
North  40   98.0   12.0    97.0       75      125
South  40  131.0   68.0   101.0       80      410
\`\`\`

South has cluttered vans and has lost the gains of last year’s project. Which conclusion is BEST supported?`,options:["North shows outliers, so 5S should start at North","South needs no action because its median is close to North’s","Both depots need a new Gage R&R before any 5S work","South shows outliers and lost gains, signs that 5S is needed there"],answer:3,hint:"The book names two signs that 5S is needed.",steps:[{title:"Key idea",body:"Book p. 513: outliers in the project metric and loss of initial gains are signs that 5S is needed."},{title:"Apply to the stem",body:"South: maximum 410 against a median of 101.0, StDev 68.0 — outliers — plus lost gains."}],final:"South: outliers + lost gains → 5S → answer **D**",whyWrong:["Incorrect — North’s maximum of 125 is close to its median; South has the extreme value.","Incorrect — similar medians hide South’s outliers (maximum 410, StDev 68.0).","Incorrect — nothing in the output points to a measurement problem.",""],bookRef:"Book p. 513"},{id:"sv-1-1339",phase:1,topic:"1.4.5",qtype:"true-false",difficulty:1,stem:"According to the book, the orderliness created by Straighten removes waste in office work as well as in production. True or False?",options:["True","False"],answer:0,hint:"5S is not only for the shop floor.",steps:[{title:"Key idea",body:"Book p. 506: orderliness removes waste in both production and office work."},{title:"Apply to the stem",body:"Digital 5S on drives, queues and dashboards applies the same idea."}],final:"Office and production → **True** (answer **A**)",whyWrong:["","Incorrect — the book says orderliness removes waste in both production and office work."],bookRef:"Book p. 506"},{id:"sv-1-1340",phase:1,topic:"1.4.5",qtype:"sequence",difficulty:3,stem:`A service desk applies 5S to its ticket queue. Put the activities in 5S order:

- **P** Colour-code ageing tickets so everyone sees the same warning
- **Q** Close stale and duplicate tickets
- **R** Set clear ticket categories so each ticket has one home
- **S** Review the queue against the standard every week
- **T** Clear resolved clutter and fix the source of duplicate tickets`,options:["Q → R → T → P → S","R → Q → T → P → S","Q → R → P → T → S","Q → T → R → P → S"],answer:0,hint:"Map each activity to an S, then follow Sort → Straighten → Shine → Standardize → Self-Discipline.",steps:[{title:"Key idea",body:"Close stale = Sort; categories = Straighten; clear clutter and fix source = Shine; colour code = Standardize; weekly review = Self-Discipline."},{title:"Apply to the stem",body:"Q → R → T → P → S."}],final:"Q → R → T → P → S → answer **A**",whyWrong:["","Incorrect — stale tickets are removed (Sort) before categories are set (Straighten).","Incorrect — cleaning and fixing sources (Shine) comes before the visual standard (Standardize).","Incorrect — categories (Straighten) come before clean-up (Shine)."],bookRef:"Book pp. 504–508"}];export{e as items};
